task automatic drive_bus();
  repeat (10) @(posedge clk);       // wait for 10 rising edges
  enable <= 1'b1;                   // <=: the DUT samples the old value on this edge

// No lifetime keyword in a module: this task is STATIC,
  // so every call shares one copy of id.  ...  rest = fact_static(n - 1);   // the inner call copies a new value into n
    return rest * n;             // reads n after the call
